"""Subscription task execution page using the shared entertainment-console layout."""


def tasks_html() -> str:
    return r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>订阅任务 · 115网盘转存助手</title><style>
:root{--line:#174c54;--gold:#d3b370;--cyan:#16b9d1;--text:#e7ddc7;--muted:#978b73}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 72% 3%,#2a2013 0,#090805 40%,#050504 100%);color:var(--text);font:14px system-ui,-apple-system,"Microsoft YaHei",sans-serif;min-height:100vh}.shell{display:grid;grid-template-columns:285px minmax(0,1fr);min-height:100vh}.side{position:sticky;top:0;height:100vh;background:#090805ef;border-right:1px solid var(--line);padding:18px 10px;display:flex;flex-direction:column}.logo{font-size:26px;font-weight:800;color:var(--gold);padding:4px 10px 37px}.group{font-size:12px;color:#776c58;margin:14px 7px 7px;border-bottom:1px solid #3e341f;padding-bottom:9px}.nav{display:block;color:#c0ae89;text-decoration:none;padding:15px 20px;margin:3px 0;border-radius:13px;font-size:16px;font-weight:700}.nav:hover,.nav.active{background:#113a40;color:#39d4e9;outline:1px solid #176b75}.main{min-width:0}.top{height:68px;display:flex;align-items:center;gap:24px;padding:0 30px;background:#080705ed;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:10}.heading{font-size:25px;font-weight:800;color:#35c7dd}.tabs{display:flex;align-self:stretch}.tab{border:0;background:none;color:#9d9076;padding:0 20px;border-bottom:3px solid transparent;font-weight:700}.tab.active{color:#26c7df;border-color:#16b9d1}.refresh{margin-left:auto;border:1px solid #275a5e;background:#17150f;color:#d7bf8b;border-radius:11px;padding:10px 20px;cursor:pointer}.wrap{max-width:1560px;margin:auto;padding:25px 32px}.toolbar{display:flex;gap:10px;justify-content:space-between;align-items:center;margin-bottom:16px}.toolbar h2{margin:0;color:#d9c18b}.muted{color:var(--muted)}.panel{background:#0f0e0a;border:1px solid var(--line);border-radius:16px;overflow:hidden;min-height:620px}.thead,.row{display:grid;grid-template-columns:70px 110px 90px 165px 70px 70px 70px 70px 70px 70px minmax(220px,1fr) 70px;align-items:center;gap:8px;padding:14px 16px}.thead{color:#90836b;background:#1a160e;border-bottom:1px solid var(--line);font-size:13px}.row{min-height:91px;border-bottom:1px solid #123f46}.row:hover{background:#15120c}.id{font-weight:800;color:#d5bd86}.tag{display:inline-block;padding:5px 9px;border-radius:12px;background:#12343b;color:#4fdbed;font-size:12px}.tag.good{background:#133622;color:#66dda0}.tag.bad{background:#3b1e20;color:#ff8790}.num{font-weight:800}.success{color:#59da90}.failed{color:#ff7f8b}.summary{color:#b4a487;line-height:1.55}.detail{color:#27cce4;background:none;border:0;cursor:pointer}.state{text-align:center;padding:130px 20px;color:#9d917d}.state h2{color:#d8bc7c}.pager{display:flex;justify-content:center;align-items:center;gap:12px;padding:18px}.pager button{border:1px solid #235b63;background:#17140e;color:#d8bd7f;border-radius:50%;width:38px;height:38px}.pager button:disabled{opacity:.3}.skeleton{height:90px;margin:0 16px;border-bottom:1px solid #143b40;background:linear-gradient(90deg,#11100c 25%,#242017 38%,#11100c 63%);background-size:400% 100%;animation:shine 1.2s infinite}@keyframes shine{to{background-position:-100% 0}}.modal{position:fixed;inset:0;background:#000b;display:none;place-items:center;z-index:50;padding:18px}.modal.open{display:grid}.dialog{width:min(760px,95vw);max-height:85vh;overflow:auto;background:#15120c;border:1px solid #23717c;border-radius:16px;padding:22px}.close{float:right;background:none;border:0;color:#ddd;font-size:25px}.entry{padding:10px 0;border-top:1px solid #3a301f;color:#b9aa8f}
@media(max-width:1250px){.shell{grid-template-columns:235px minmax(0,1fr)}.thead,.row{grid-template-columns:55px 100px 85px 145px 60px 60px 60px minmax(180px,1fr) 60px}.optional{display:none}.wrap{padding:20px}}
@media(max-width:850px){.shell{display:block}.side{display:none}.top{padding:0 12px}.heading{font-size:20px}.wrap{padding:12px}.thead{display:none}.panel{border:0;background:none}.row{display:grid;grid-template-columns:65px 1fr auto;border:1px solid var(--line);border-radius:12px;margin-bottom:10px;padding:14px;background:#12100b}.row>div{display:block}.row .summary{grid-column:1/-1}.row .detail{grid-column:3;grid-row:1/3}}
</style></head><body><div class="shell"><aside class="side"><div class="logo">◉ Moon Dream</div><div class="group">发现</div><a class="nav" href="/web/rankings">🏆 榜单</a><a class="nav" href="/explore">◉ 遨游</a><div class="group">订阅</div><a class="nav" href="/subscriptions">☷ 订阅列表</a><a class="nav active" href="/tasks">▣ 订阅任务</a><a class="nav" href="/unlocks">◴ 解锁记录</a><div class="group">系统</div><a class="nav" href="/authorizations">⌘ 授权中心</a><a class="nav" href="/settings">⚙ 业务设置</a><a class="nav" href="/telegram">✈ Telegram</a></aside><section class="main"><header class="top"><div class="heading">⏰ 订阅任务</div><div class="tabs"><div class="tab">⚙ 调度设置</div><div class="tab active">▣ 执行记录 <span id="count">0</span></div></div><button class="refresh" id="refresh">↻ 刷新</button></header><main class="wrap"><div class="toolbar"><div><h2>执行记录</h2><div class="muted">每次运行都会记录资源匹配、解锁和保存结果。</div></div><span class="tag good">● 订阅任务已启用</span></div><section class="panel"><div class="thead"><div>执行</div><div>状态</div><div>触发</div><div>开始时间</div><div>耗时</div><div>处理</div><div>成功</div><div>失败</div><div class="optional">跳过</div><div class="optional">保存</div><div>摘要</div><div>操作</div></div><div id="list"></div><div id="pager" class="pager"></div></section></main></section></div><div class="modal" id="modal"><div class="dialog"><button class="close" id="close">×</button><div id="detail"></div></div></div><script>
const S={page:1,page_size:10};const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const dt=v=>v?new Date(Number(v)*1000).toLocaleString('zh-CN',{hour12:false}):'-';function info(s){return {resource_found:['发现资源','good'],waiting_output:['等待输出',''],failed:['执行失败','bad'],completed:['已完成','good'],running:['执行中','']}[s]||[s||'未知','']};function skeleton(){return '<div class="skeleton"></div>'.repeat(5)}
function task(x){const st=info(x.status),ok=x.status==='resource_found'||x.status==='completed'?x.transfer_count||0:0,bad=x.status==='failed'?1:0;return `<article class="row"><div class="id">#${x.id}</div><div><span class="tag ${st[1]}">${st[0]}</span></div><div>手动</div><div>${dt(x.created_at)}</div><div>-</div><div class="num">${x.resource_count||0}</div><div class="num success">${ok}</div><div class="num failed">${bad}</div><div class="optional">0</div><div class="optional">${x.transfer_count||0}</div><div class="summary">${esc(x.title||'订阅任务')}：命中 ${x.resource_count||0} 条资源，保存 ${x.transfer_count||0} 条。${x.error?'错误：'+esc(x.error):''}</div><button class="detail" data-id="${x.id}">详情 ›</button></article>`}
async function load(){ $('#list').innerHTML=skeleton();try{const r=await fetch(`/api/web/tasks?page=${S.page}&page_size=${S.page_size}`);if(!r.ok)throw Error('接口返回 '+r.status);const d=await r.json();$('#count').textContent=d.total;if(!d.items.length)$('#list').innerHTML='<div class="state"><h2>暂无执行记录</h2><p>建立订阅并执行后，任务结果会显示在这里。</p></div>';else{$('#list').innerHTML=d.items.map(task).join('');document.querySelectorAll('.detail').forEach(b=>b.onclick=()=>show(+b.dataset.id))}$('#pager').innerHTML=`<button id="prev" ${d.page<=1?'disabled':''}>‹</button><span>第 ${d.page} / ${d.total_pages} 页 · 共 ${d.total} 条</span><button id="next" ${!d.has_more?'disabled':''}>›</button>`;$('#prev').onclick=()=>{S.page--;load()};$('#next').onclick=()=>{S.page++;load()}}catch(e){$('#list').innerHTML=`<div class="state"><h2>任务记录加载失败</h2><p>${esc(e.message)}</p></div>`}}
async function show(id){const r=await fetch('/api/web/tasks/'+id),d=await r.json();$('#detail').innerHTML=`<h2>执行 #${d.task.id} · ${esc(d.task.title||'订阅任务')}</h2><div class="entry">状态：${esc(info(d.task.status)[0])}</div><div class="entry">开始时间：${dt(d.task.created_at)}</div><div class="entry">资源命中：${d.task.resource_count||0} 条</div><div class="entry">保存：${d.task.transfer_count||0} 次</div>${d.task.error?`<div class="entry">错误原因：${esc(d.task.error)}</div>`:''}`;$('#modal').classList.add('open')}$('#refresh').onclick=load;$('#close').onclick=()=>$('#modal').classList.remove('open');$('#modal').onclick=e=>{if(e.target.id==='modal')$('#modal').classList.remove('open')};load();
</script></body></html>'''
